// What the Personas pages show, worked out from the personas and their
// tests, with the signals from each (Signals' plug: none while Signals is
// not installed).
import { faceOf, } from "@software-factory/core";
import { newestFirst, signalRows, } from "../../kobble/signal-rows.js";
import { Refused } from "../../refused.js";
const going = (test) => test.status === "queued" || test.status === "running";
export function missionsNow(store) {
    const personas = new Map(store.all("personas").map((one) => [one.id, one]));
    return store
        .all("tests")
        .filter(going)
        .flatMap((test) => {
        const persona = personas.get(test.persona);
        if (!persona)
            return [];
        return [
            {
                id: test.id,
                persona: persona.id,
                name: persona.name,
                face: faceOf(persona),
                status: test.status,
                doing: test.doing ?? null,
            },
        ];
    });
}
export function personasView(store, signals) {
    const busy = new Set(missionsNow(store).map((one) => one.persona));
    return {
        personas: store.all("personas").map((persona) => ({
            ...persona,
            face: faceOf(persona),
            signals: signals.filter((signal) => signal.persona === persona.id).length,
            onMission: busy.has(persona.id),
        })),
    };
}
// One persona and every signal from them, whatever became of it.
export function personaPage(store, id, signals) {
    const persona = store.get("personas", id);
    if (!persona)
        throw new Refused(`There is no persona “${id}”.`);
    const theirs = signals.filter((signal) => signal.persona === persona.id);
    return {
        persona: { ...persona, face: faceOf(persona) },
        signals: signalRows(newestFirst(theirs), [persona]),
        tests: testsOf(store, persona.id),
    };
}
// A persona's tests, the last one first.
export function testsOf(store, persona) {
    return store
        .all("tests")
        .filter((test) => test.persona === persona)
        .reverse();
}
// One test, its persona, and the signals it filed.
export function testPage(store, id, signals) {
    const test = store.get("tests", id);
    if (!test)
        throw new Refused(`There is no test “${id}”.`);
    const persona = store.get("personas", test.persona);
    if (!persona)
        throw new Refused(`There is no persona “${test.persona}”.`);
    const filed = signals.filter((signal) => test.signals.includes(signal.id));
    return {
        test,
        persona: { ...persona, face: faceOf(persona) },
        signals: signalRows(filed, [persona]),
    };
}
